// checkoutConversionFix.js - Ensure paidEvents increment on successful checkout
// This module intercepts the checkout completion flow and forces a revenue event.

const revenueModule = require('./revenueModule');

module.exports = function attachCheckoutHook(app) {
  app.post('/api/checkout/complete', (req, res, next) => {
    const originalJson = res.json.bind(res);
    res.json = function (body) {
      if (body && body.success) {
        // Force a paid event
        revenueModule.recordEvent({
          type: 'paid',
          amount: body.amount || 0,
          currency: 'USD',
          timestamp: Date.now()
        });
      }
      return originalJson(body);
    };
    next();
  });
};
